package com.hibernate.ecommerce.repository;import com.hibernate.ecommerce.model.Order;import com.hibernate.ecommerce.model.state;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import java.util.List;public interface OrderRepository extends JpaRepository<Order, Long> {    @Query("SELECT COUNT(o) > 0 FROM Order o JOIN o.orderdetails od WHERE od.product.id = :productId")    boolean existsOrderDetailByProductId(@Param("productId") Long productId);    @Query("SELECT o FROM Order o " +            "WHERE o.client.id = :clientId " +            "AND (:state IS NULL OR o.state = :state)")    List<Order> findByClientIdAndOptionalState(@Param("clientId") Long clientId,                                               @Param("state") state state);}